// Generates the Material 3 design tokens for both apps from one seed colour.
//
//   npm run generate   writes design/tokens.json, the Compose theme file and the SwiftUI theme file
//   npm run check      fails when a generated file is out of date (CI)
//
// Do not edit the generated files by hand. Change SEED or the tables below, then run the generator.

import { readFileSync, writeFileSync, mkdirSync } from "node:fs";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import {
  Blend, Hct, MaterialDynamicColors, SchemeTonalSpot, TonalPalette, argbFromHex, hexFromArgb,
} from "@material/material-color-utilities";

const SEED = "#0B7A75"; // TripSplit teal
const POSITIVE_SOURCE = "#2E7D32"; // money owed to you; harmonised toward the seed

const root = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const OUT = {
  tokens: resolve(root, "design/tokens.json"),
  kotlin: resolve(root, "android/app/src/main/java/com/olcayertas/tripsplit/ui/theme/Tokens.kt"),
  swift: resolve(root, "apple/App/Theme/Tokens.swift"),
};

const ROLES = Object.keys(MaterialDynamicColors).filter(
  (k) => typeof MaterialDynamicColors[k]?.getArgb === "function" && !k.endsWith("PaletteKeyColor"),
);

function scheme(isDark) {
  const s = new SchemeTonalSpot(Hct.fromInt(argbFromHex(SEED)), isDark, 0);
  const roles = Object.fromEntries(ROLES.map((r) => [r, hexFromArgb(MaterialDynamicColors[r].getArgb(s))]));
  const positive = TonalPalette.fromInt(Blend.harmonize(argbFromHex(POSITIVE_SOURCE), argbFromHex(SEED)));
  const t = (tone) => hexFromArgb(positive.tone(tone));
  Object.assign(roles, isDark
    ? { positive: t(80), onPositive: t(20), positiveContainer: t(30), onPositiveContainer: t(90) }
    : { positive: t(40), onPositive: t(100), positiveContainer: t(90), onPositiveContainer: t(10) });
  return roles;
}

// Material 3 baseline type scale: [size, lineHeight, weight, tracking] in sp / pt.
const TYPE = {
  displayLarge: [57, 64, 400, -0.25], displayMedium: [45, 52, 400, 0], displaySmall: [36, 44, 400, 0],
  headlineLarge: [32, 40, 400, 0], headlineMedium: [28, 36, 400, 0], headlineSmall: [24, 32, 400, 0],
  titleLarge: [22, 28, 400, 0], titleMedium: [16, 24, 500, 0.15], titleSmall: [14, 20, 500, 0.1],
  bodyLarge: [16, 24, 400, 0.5], bodyMedium: [14, 20, 400, 0.25], bodySmall: [12, 16, 400, 0.4],
  labelLarge: [14, 20, 500, 0.1], labelMedium: [12, 16, 500, 0.5], labelSmall: [11, 16, 500, 0.5],
};

// Material 3 Expressive shape scale: corner radius in dp / pt.
const SHAPE = {
  none: 0, extraSmall: 4, small: 8, medium: 12, large: 16, largeIncreased: 20,
  extraLarge: 28, extraLargeIncreased: 32, extraExtraLarge: 48,
};

const SPACING = { xxs: 2, xs: 4, s: 8, m: 12, l: 16, xl: 24, xxl: 32, xxxl: 48 };

const tokens = {
  seed: SEED,
  positiveSource: POSITIVE_SOURCE,
  color: { light: scheme(false), dark: scheme(true) },
  type: Object.fromEntries(Object.entries(TYPE).map(([k, [size, lineHeight, weight, tracking]]) =>
    [k, { size, lineHeight, weight, tracking }])),
  shape: SHAPE,
  spacing: SPACING,
};

const header = (comment) => `${comment} Generated by design/generate.mjs from design/tokens.json. Do not edit.\n`;
const argb = (hex) => `0xFF${hex.slice(1).toUpperCase()}`;
const cap = (s) => s[0].toUpperCase() + s.slice(1);

// --- Kotlin (Jetpack Compose Material 3) ---------------------------------------------------------

const COMPOSE_ROLES = ROLES.filter((r) => r !== "shadow");

function kotlin() {
  const L = tokens.color.light;
  const D = tokens.color.dark;
  // Compose's lightColorScheme/darkColorScheme take every role except shadow and the Fixed roles.
  const schemeArgs = (c) => COMPOSE_ROLES.filter((r) => !r.includes("Fixed"))
    .map((r) => `    ${r} = Color(${argb(c[r])}),`).join("\n");
  const ext = (c) => ["positive", "onPositive", "positiveContainer", "onPositiveContainer"]
    .map((r) => `    ${r} = Color(${argb(c[r])}),`).join("\n");
  const weight = (w) => ({ 400: "FontWeight.Normal", 500: "FontWeight.Medium", 700: "FontWeight.Bold" })[w];
  const type = Object.entries(tokens.type).map(([k, v]) =>
    `    ${k} = TextStyle(fontSize = ${v.size}.sp, lineHeight = ${v.lineHeight}.sp, fontWeight = ${weight(v.weight)}, letterSpacing = ${v.tracking}.sp),`).join("\n");
  return `${header("//")}
package com.olcayertas.tripsplit.ui.theme

import androidx.compose.material3.Typography
import androidx.compose.material3.darkColorScheme
import androidx.compose.material3.lightColorScheme
import androidx.compose.runtime.Immutable
import androidx.compose.ui.graphics.Color
import androidx.compose.ui.text.TextStyle
import androidx.compose.ui.text.font.FontWeight
import androidx.compose.ui.unit.dp
import androidx.compose.ui.unit.sp

const val SEED_COLOR: Long = ${argb(tokens.seed)}

val LightColors = lightColorScheme(
${schemeArgs(L)}
)

val DarkColors = darkColorScheme(
${schemeArgs(D)}
)

/** Roles that Material 3 does not have: money owed to the user. */
@Immutable
data class ExtendedColors(
    val positive: Color,
    val onPositive: Color,
    val positiveContainer: Color,
    val onPositiveContainer: Color,
)

val LightExtendedColors = ExtendedColors(
${ext(L)}
)

val DarkExtendedColors = ExtendedColors(
${ext(D)}
)

val TripSplitTypography = Typography(
${type}
)

object Corner {
${Object.entries(SHAPE).map(([k, v]) => `    val ${k} = ${v}.dp`).join("\n")}
}

object Spacing {
${Object.entries(SPACING).map(([k, v]) => `    val ${k} = ${v}.dp`).join("\n")}
}
`;
}

// --- Swift (SwiftUI) -----------------------------------------------------------------------------

function swift() {
  const L = tokens.color.light;
  const D = tokens.color.dark;
  const roles = [...ROLES.filter((r) => r !== "shadow"), "positive", "onPositive", "positiveContainer", "onPositiveContainer"];
  const hex = (h) => `0x${h.slice(1).toUpperCase()}`;
  const weight = (w) => ({ 400: ".regular", 500: ".medium", 700: ".bold" })[w];
  return `${header("//")}
import SwiftUI
import UIKit

/// Material 3 colour roles. Each colour follows the light/dark appearance.
enum M3Color {
${roles.map((r) => `    static let ${r} = Color(uiColor: .m3(light: ${hex(L[r])}, dark: ${hex(D[r])}))`).join("\n")}
}

/// Material 3 baseline type scale on SF Pro, with Dynamic Type.
enum M3Type {
${Object.entries(tokens.type).map(([k, v]) =>
    `    static let ${k} = M3TextStyle(size: ${v.size}, lineHeight: ${v.lineHeight}, weight: ${weight(v.weight)}, tracking: ${v.tracking})`).join("\n")}
}

enum M3Corner {
${Object.entries(SHAPE).map(([k, v]) => `    static let ${k}: CGFloat = ${v}`).join("\n")}
}

enum M3Spacing {
${Object.entries(SPACING).map(([k, v]) => `    static let ${k}: CGFloat = ${v}`).join("\n")}
}

struct M3TextStyle: Sendable {
    let size: CGFloat
    let lineHeight: CGFloat
    let weight: Font.Weight
    let tracking: CGFloat
}

extension UIColor {
    static func m3(light: UInt32, dark: UInt32) -> UIColor {
        UIColor { traits in
            let v = traits.userInterfaceStyle == .dark ? dark : light
            return UIColor(
                red: CGFloat((v >> 16) & 0xFF) / 255, green: CGFloat((v >> 8) & 0xFF) / 255,
                blue: CGFloat(v & 0xFF) / 255, alpha: 1)
        }
    }
}
`;
}

const outputs = [
  [OUT.tokens, JSON.stringify(tokens, null, 2) + "\n"],
  [OUT.kotlin, kotlin()],
  [OUT.swift, swift()],
];

const check = process.argv.includes("--check");
let stale = [];
for (const [path, text] of outputs) {
  if (check) {
    let current = null;
    try { current = readFileSync(path, "utf8"); } catch {}
    if (current !== text) stale.push(path);
  } else {
    mkdirSync(dirname(path), { recursive: true });
    writeFileSync(path, text);
  }
}
if (stale.length) {
  console.error("stale design outputs:\n" + stale.join("\n"));
  process.exit(1);
}
console.log(check ? "ok" : `wrote ${outputs.length} files`);
